export function recordDraw(ledger: Ledger, boat: string, day: number, minute: number, volume: number): Entry {
  const last = ledger.entries.length > 0 ? ledger.entries[ledger.entries.length - 1] : undefined;
  if (last !== undefined && last.kind === "draw" && last.boat === boat && last.day === day) {
    // Run the normal draw on a scratch copy so a refused volume throws exactly as before
    // and leaves the real ledger untouched.
    postNewDraw({ ...ledger, entries: ledger.entries.slice() }, boat, day, minute, volume);
    last.volume += volume;
    return last;
  }
  return postNewDraw(ledger, boat, day, minute, volume);
}

